/**
 * Какой язык показывать.
 *
 * Сначала выбор человека, потом язык браузера, иначе украинский.
 * Украинский по умолчанию, а не английский: продукт продаётся здесь.
 */
function langGet(){
  try {
    var saved = localStorage.getItem('rz.lang');
    if (saved && DICT[saved]) return saved;
    if (saved === 'uk') return 'uk';
  } catch(e){}
  var nav = (navigator.language || '').slice(0, 2).toLowerCase();
  if (nav === 'pl') return 'pl';
  if (nav === 'uk' || nav === 'ru') return 'uk';
  return nav === 'en' ? 'en' : 'uk';
}

function langSet(id){
  try { localStorage.setItem('rz.lang', id) } catch(e){}
  LANG = id;
  applyLang();
}

var LANG = langGet();

/** Перевести строку. Нет перевода — остаётся украинская. */
function L(text){
  var d = DICT[LANG];
  return (d && d[text]) || text;
}

/**
 * Перевод статической разметки.
 *
 * Подписи в каркасе страницы написаны по-украински прямо в HTML.
 * Первый проход запоминает исходную строку в data-uk, дальше перевод
 * всегда считается от неё — иначе после двух переключений языка
 * переводился бы уже перевод.
 */
function applyLang(){
  document.documentElement.setAttribute('lang', LANG);
  Array.prototype.forEach.call(document.querySelectorAll('[data-t]'), function(n){
    if (!n.dataset.uk) n.dataset.uk = n.textContent.trim();
    n.textContent = L(n.dataset.uk);
  });
  Array.prototype.forEach.call(document.querySelectorAll('[data-tp]'), function(n){
    if (!n.dataset.ukp) n.dataset.ukp = n.getAttribute('placeholder') || '';
    n.setAttribute('placeholder', L(n.dataset.ukp));
  });
  Array.prototype.forEach.call(document.querySelectorAll('[data-tt]'), function(n){
    if (!n.dataset.ukt) n.dataset.ukt = n.getAttribute('title') || '';
    n.setAttribute('title', L(n.dataset.ukt));
  });
}
